#!/usr/bin/env python3
"""Pin R preparations and correctness evidence, without running performance work."""
from pathlib import Path
import json,hashlib,os,subprocess
import r_loc
G=Path(__file__).resolve().parent
R=G/'.build/toolchains/R-4.6.1/bin/Rscript'
H=G/'.build/toolchains/R-4.6.1'
LIB=G/'.build/toolchains/r-library'
def sha(p):
 with Path(p).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
pins=json.loads((G/'r-install-pins.json').read_text())
small=json.loads((G/'results/r/small-validation.json').read_text())
adversarial=json.loads((G/'results/r/adversarial-validation.json').read_text())
assert len(small)==22 and all(r['reference_match'] for r in small.values())
assert all(r['reference_match'] for r in adversarial)
upstream=json.loads((G/'upstream/r/provenance.json').read_text())
originals={row['upstream_path'].removeprefix('Benchmarks/shootout/'):row for row in upstream['files']}
# Handle provenance emitted with repository-relative or shootout-relative paths.
originals.update({row['upstream_path'].split('shootout/')[-1]:row for row in upstream['files']})
version=subprocess.check_output([str(R),'--version'],text=True).strip()
runtime={'path':str(R),'sha256':sha(R),'version':version,'architecture':'aarch64-apple-darwin23','distribution_url':pins['runtime']['url'],'distribution_sha256':pins['runtime']['sha256'],'provenance':'Official CRAN R binary, relocated as a portable distribution by Posit r-builds','primary_runtime_documentation':'https://github.com/rstudio/r-builds/blob/main/macos/README.md','pins':{str(p):sha(p) for p in [H/'bin/Rscript',H/'bin/Rscript.bin',H/'bin/exec/R',H/'lib/libR.dylib',H/'library/base/R/base.rdb',H/'library/compiler/R/compiler.rdb',H/'library/parallel/R/parallel.rdb'] if p.exists()}}
runtime['pins'].update({str(p):sha(p) for p in list((H/'lib').glob('*.dylib'))+[H/'library/parallel/libs/parallel.so',H/'bin/R',H/'etc/Renviron'] if p.is_file()})
for package in ['base','compiler','parallel','stats','utils','methods','datasets','graphics','grDevices']:
 for suffix in ['rdb','rdx']:
  path=H/'library'/package/'R'/(package+'.'+suffix)
  if path.is_file():runtime['pins'][str(path)]=sha(path)
gmp={'name':'gmp','version':'0.7-5.1','kind':'ordinary general-purpose arbitrary-precision integer library','package_url':'https://cran.r-project.org/package=gmp','binary_archive_url':pins['gmp_binary']['url'],'binary_archive_sha256':pins['gmp_binary']['sha256'],'source_archive_url':pins['gmp_source']['url'],'source_archive_sha256':pins['gmp_source']['sha256'],'installed_library':str(LIB/'gmp'),'pins':{str(p):sha(p) for p in [LIB/'gmp/libs/gmp.so',LIB/'gmp/R/gmp.rdb',LIB/'gmp/R/gmp.rdx',LIB/'gmp/DESCRIPTION']},'pi_division_audit':'In gmp source bigintegerR.cc:240-260, generic binary arithmetic visits each vector lane; bigmod.cc:108-110 performs mpz_tdiv_q for each lane. The two-element optimized R extraction therefore does two quotient operations, not a remainder shortcut.'}
base={'R_LIBS_USER':str(LIB),'R_ENABLE_JIT':'3','OMP_NUM_THREADS':'1','OPENBLAS_NUM_THREADS':'1','VECLIB_MAXIMUM_THREADS':'1','LC_ALL':'C'}
selected={'nbody':('nbody/nbody_3.r','nbody/nbody_3.r'),'mandelbrot':('mandelbrot/mandelbrot.r','mandelbrot/mandelbrot.r'),'spectralnorm':('spectralnorm/spectralnorm.r','spectralnorm/spectralnorm_alt_4.r'),'binarytrees':('binarytrees/binarytrees.r','binarytrees/binarytrees_2.r'),'fasta':('fasta/fasta_3.r','fasta/fasta_3.r'),'knucleotide':('knucleotide/knucleotide.r','knucleotide/knucleotide.r'),'revcomp':('reversecomplement/reversecomplement.r','reversecomplement/reversecomplement_2.r'),'regexredux':('regexdna/regexdna.r','regexdna/regexdna.r'),'fannkuchredux':('fannkuch/fannkuchredux.r','fannkuch/fannkuchredux.r'),'pidigits':('pidigits/pidigits.r','pidigits/pidigits.r')}
adaptations={
 'nbody':['Locally authored matrix/vector adaptations of the archived canonical constants and Newtonian update. Compact uses all ten unique pair deltas; optimized performs all 25 directed differences with zero diagonal force.','Fixed nine-decimal energy output; canonical momentum offset, dt=0.01 and all requested timesteps. No native nbody kernel.'],
 'mandelbrot':['Replace the old complex all-iteration source with explicit binary64 real/imaginary recurrence, exact P4 header and required bit padding.','Compact computes every lane through 50 iterations; optimized removes escaped lanes and maps row tasks over at most eight standard R fork workers, preserving all pixels and the complete recurrence.'],
 'spectralnorm':['Canonical implicit A and A-transpose multiplications with a numerator divided by each denominator every application; remove archived matrix memoization.','Compact vectorizes one output row; optimized bounds temporary denominator matrices to 128 rows. Ten full alternating A-transpose-A iterations and fixed nine-decimal output.'],
 'binarytrees':['Replace old item-valued positive/negative trees with the modern complete node-count workload. Every node, including each leaf, is a fresh R list.','Retain the long-lived tree until its final traversal. Compact sequential construction/check; optimized uses eight fresh standard R PSOCK workers for depth tasks, with all tree construction/check code visible in R.'],
 'fasta':['Restore and retain direct seed/139968 binary64 division and unscaled sequential CDF probabilities; strict CDF threshold via generic findInterval. No period cache or integer-scaled thresholds.','Canonical ALU, 2n/3n/5n record sizes, headers, 60-column wrapping and sequential RNG state passed from IUB to Human. Optimized performs generic vector affine-prefix scans independently for each whole-line block, materializing every ordered seed and draw. Modular composition intermediates are below 2^36 and exact in binary64; no seed period or output cache.'],
 'knucleotide':['Read canonical stdin THREE record, tolerate comments/CRLF/case/irregular lines and stop at the next header.','Construct all seven complete growing frequency dictionaries at k=1,2,3,4,6,12,18, not only query counts. Compact merges bounded generic table histograms; optimized grows a generic match dictionary and tabulates every window.','Lexical tie ordering, exact frequency formatting, and empty maps for sequences shorter than each width.'],
 'revcomp':['Correct the archived program, which only complemented individual lines: concatenate each complete record, reverse it, complement every IUB symbol, uppercase and rewrap at 60 columns.','Optimized reads from record ends in bounded raw-array blocks and applies an ordinary 256-byte translation table. All record data and transformations remain in R application source.'],
 'regexredux':['Update old regex-dna to all nine modern redux match counts and five ordered replacements, plus complete initial/cleaned/final lengths.','Base R PCRE byte regex operations, case-sensitive canonical patterns and correct zero/one/multiple match counting. Compact and optimized are the same source because the generic native regex operations already provide the optimized algorithm; measure once and use the result for both forms.'],
 'fannkuchredux':['Canonical complete permutation enumeration, prefix reversal counts, alternating signed checksum and maximal flip count; fix archived treatment of permutations beginning with 1.','Optimized partitions the exact factorial rank space over at most eight ordinary fork workers, independently initializes each factoradic range and evaluates every permutation. Reusable general prefix/reversal/rotation index vectors remove repeated range allocations and rev() dispatch, without caching permutations or flip results.'],
 'pidigits':['Use the ordinary CRAN GMP arbitrary-precision library in place of the archived in-source integer library; every benchmark loop and decision remains in R.','Perform both (3*num+acc)/den and (4*num+acc)/den quotients for every actually tested candidate; replace the archived single-division remainder shortcut. Compact additionally extracts before the allowed impossible-candidate guard; optimized uses that guard and generic two-lane division executing both quotients.','Exact ten-digit lines, tab/colon count, and blank padding for a final partial line.']}
rows=[]
for benchmark,paths in selected.items():
 for index,variant in enumerate(['compact','optimized']+(['array-compact','array-batched'] if benchmark=='fannkuchredux' else [])):
  source=G/'sources/r'/benchmark/(variant+'.R')
  sid=benchmark+'-r-'+variant
  original=originals[paths[min(index,1)]]
  original_path=original.get('source',original.get('local_path',original.get('downloaded_source')))
  if original_path is None:original_path=str(G/'upstream/r'/paths[index])
  command=[str(R),'--vanilla',str(source)]+([] if benchmark in ['knucleotide','revcomp','regexredux'] else ['{n}'])
  validation=small[sid]
  assert validation.get('source_sha256',sha(source))==sha(source)
  loc=r_loc.normalize(source.read_text())
  row={'id':sid,'key':benchmark+':'+sid,'benchmark':benchmark,'language':'r','variant':'compact' if variant in ['compact','array-compact'] else 'optimized','profile':'compact' if variant in ['compact','array-compact'] else 'optimized','source_profile':variant,'source':str(source),'source_sha256':sha(source),'command':command,'build_command':[],'build_status':'not-required','execution_mode':'interpreted','runtime':runtime,'runtime_sha256':sha(R),'runtime_environment':base,'library_support':[gmp] if benchmark=='pidigits' else [],'source_url':original['source_url'],'upstream_source':original_path,'upstream_sha256':original['sha256'],'upstream_revision':upstream['revision'],'adaptations':adaptations[benchmark],'algorithm':{'strict':True,'native_benchmark_kernel':False,'reason':'Complete unchanged canonical workload in visible R application code; only ordinary general-purpose standard/package operations.','arithmetic':'binary64' if benchmark in ['nbody','spectralnorm','mandelbrot','fasta'] else 'unbounded-integer' if benchmark=='pidigits' else 'integer'},'small_validation':validation,'adversarial_validation':[r for r in adversarial if r['benchmark']==benchmark and r['variant']==variant],'loc':loc['normalized_loc'],'physical_loc':loc['physical_loc'],'loc_expansions':loc['expansions'],'loc_review':'One independent assignment/statement per line. Long literal arrays and nested calls remain one expression; no independent assignment packing discount.','eligible_for_chart':False,'measurement_status':'not-measured','recommended_timeout_seconds':86400 if benchmark in ['nbody','fannkuchredux','binarytrees'] else 14400,'maximum_workers':8 if variant in ['optimized','array-batched'] and benchmark in ['mandelbrot','binarytrees','fannkuchredux'] else 1}
  if benchmark=='fannkuchredux' and variant in ['compact','optimized']:
   row.update(excluded=True,shortlist_status='archived-validated-candidate',shortlist_reason='Preserved original35/50LOC forms and validation. New30/37LOC bounded array forms pass the same work checks and improve/comparably match guarded planning probes; full timings select only this transparent shortlist, not a claimed global optimum.')
  if variant in ['array-compact','array-batched']:row['adaptations']=row['adaptations']+['Additional array candidate: bounded n-by-8192 factoradic permutation matrices; every rank independently materialized, every prefix reversal via general index gather over active columns, canonical rank parity. Serial compact or at most eight ordinary fork workers. No permutation/flip cache or native workload kernel.']
  if benchmark=='regexredux':row['equivalent_candidate_group']='regexredux-r-base-pcre';row['timing_alias_of']='regexredux-r-compact' if variant=='optimized' else None
  if benchmark=='binarytrees':row['allocation_fixture']={'path':str(G/'results/r/semantics-fixtures.tsv'),'sha256':sha(G/'results/r/semantics-fixtures.tsv'),'depth':5,'total_nodes':63,'unique_node_addresses':63,'leaf_allocation':True}
  if benchmark=='knucleotide':row['complete_map_fixture']={'path':str(G/'results/r/semantics-fixtures.tsv'),'sha256':sha(G/'results/r/semantics-fixtures.tsv'),'all_seven_maps_match_independent_python_reference':True}
  if benchmark=='fasta':row['cdf_fixture']={'path':str(G/'results/r/semantics-fixtures.tsv'),'sha256':sha(G/'results/r/semantics-fixtures.tsv'),'binary64_capability':'No extended long-double arithmetic','sequential_cdf_rounding_equal':True,'rng_period_coverage_correctness_case':'n=20000, 160000 fresh random draws; entire RNG period covered without using any period cache.'}
  if benchmark=='pidigits':row['quotient_work_fixture']={'path':str(G/'results/r/pidigits-work-fixtures.tsv'),'sha256':sha(G/'results/r/pidigits-work-fixtures.tsv'),'digits':37,'both_extracts_every_tested_candidate':True,'rows':[line.split('\t') for line in (G/'results/r/pidigits-work-fixtures.tsv').read_text().splitlines()]}
  rows.append(row)
manifest={'status':'prepared','language':'r','runtime':runtime,'install_pins':str(G/'r-install-pins.json'),'install_command':['python3',str(G/'install_r_runtime.py')],'preparation_command':['python3',str(G/'prepare_r_sources.py')],'validation_commands':[['python3',str(G/'validate_r.py')],['python3',str(G/'validate_r_adversarial.py')],[str(R),'--vanilla',str(G/'audit_r_semantics.R'),str(G)]],'programs':rows,'work_policy_experiment':{'path':str(G/'r-pidigits-work-policy.json'),'sha256':sha(G/'r-pidigits-work-policy.json'),'reason':'Conservative extra extraction experiment; established policy permits impossible-candidate guard. Old source hashes are not rejected.'},'protocol':'No full timings have been run by this preparer. Root owns sequential guarded fresh-process measurements at unchanged workloads, with startup, libraries, workers and all output included. Source preparation/parsing/validation/hashing excluded.','timeout_advice':'Conservative upper ceilings, not timing estimates. GNU R bytecode is interpreted, so 50m nbody, 12! fannkuch and repeated complete tree allocation may require long wall time. Run full validation once under the shared RSS/worker guard before selecting performance candidates. Never extrapolate, replace the workload, or publish small-run results as full timings.','memory_advice':'Nucleotide maps use bounded chunks and sequential widths; full input is still retained as a string. Reverse-complement compact uses full-record character vectors. Tree optimized uses fresh PSOCK workers to avoid fork copies of the retained tree. At most eight language workers.'}
(G/'r-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
(G/'results/r/source-audit.json').write_text(json.dumps({'status':'passed-small-and-adversarial','runtime':runtime,'library':gmp,'source_pins':{r['source']:r['source_sha256'] for r in rows},'source_loc':{r['id']:r['loc'] for r in rows},'all_prepared_small_cases_pass':True,'small_case_count':len(small),'all_adversarial_cases_pass':True,'adversarial_case_count':len(adversarial),'all_complete_maps_verified':14,'tree_unique_node_addresses':{'compact':63,'optimized':63},'unscaled_binary64_CDF':True,'full_performance_runs':0},indent=2)+'\n')
print('Prepared',len(rows),'R candidates; small/adversarial validation passed; preparation performs no full measurements.')
